function validate([nums, p]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(p) || p < 1 || p > 1e9) return 'p is an integer from 1 to 10^9.';
  return null;
}

