function minSubarray(nums, p) {
  const n = nums.length;
  const sums = [0];
  for (const v of nums) sums.push(sums[sums.length - 1] + v);
  const total = sums[n];
  for (let length = 0; length < n; length++) {
    for (let start = 0; start + length <= n; start++) {
      const removed = sums[start + length] - sums[start];
      if ((total - removed) % p === 0) return length;
    }
  }
  return -1;
}

