function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(1, 10);
  const top = rand() < 0.5 ? (large ? 1000 : 10) : 1e9;
  const nums = Array.from({ length: n }, () => int(1, top));
  const range = int(0, 2);
  const p = range === 0 ? int(1, large ? 100 : 6) : range === 1 ? int(1, large ? 100000 : 40) : int(1, 1e9);
  return [nums, p];
}
